  else if(S.milestones?.B_crossed_blue_door&&!S.lever_down)$('#msg').textContent='B IS THROUGH THE BLUE GATE — CLICK THE LEVER OR PULL LEVER BELOW';
  else if(S.lever_down&&!S.milestones?.A_crossed_red_bridge)$('#msg').textContent='RED BRIDGE IS UP — A GO DOWN, THEN CROSS AT THE BRIDGE';
  else if(!open&&!S.milestones?.B_crossed_blue_door)$('#msg').textContent='GATE SHUT — PUT A BACK ON THE RED PRESSURE PLATE';
  else if(open&&!S.milestones?.B_crossed_blue_door)$('#msg').textContent='KEEP A ON RED PLATE — GUIDE B THROUGH THE GLOWING BLUE GATE';
  else if(lastAction?.result==='blocked')$('#msg').textContent=`${lastAction.actor}: BLOCKED BY WALL, GATE OR HERO  |  OPEN: ${next(lastAction.actor)}`;
  else if(lastAction?.result==='hazard_reset')$('#msg').textContent=`${lastAction.actor}: WRONG-COLOR POOL — RETURNED TO SPAWN`;
  else if(lastAction?.result==='lever_down')$('#msg').textContent='BLUE LEVER PULLED — RED BRIDGE IS RAISED';
  else if(lastAction?.result==='moved')$('#msg').textContent=`${lastAction.actor} MOVED  |  OPEN: ${next(lastAction.actor)}`;
  else $('#msg').textContent=`${open?'GATE HELD OPEN':'A MUST HOLD THE RED PLATE'}  |  A OPEN: ${next('A')}  B OPEN: ${next('B')}`;
  if(S.reset_failed){$('#status').textContent='RESET LIMIT REACHED - RUN FAILED';$('#msg').textContent='THE THIRD RESET ENDED THIS RUN'}
  $('#completion').classList.toggle('show',S.complete);document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));
  document.querySelectorAll('.pad button,#interact').forEach(b=>b.disabled=!!S.reset_failed);
}
function renderFrame(){try{draw();updateHud()}catch(e){console.error('Canvas render failed',e);$('#status').textContent='DISPLAY ERROR';$('#msg').textContent=String(e.message||e).slice(0,110)}}
async function load(){try{S=await fetch('/api/state',{cache:'no-store'}).then(r=>r.json())}catch(e){$('#msg').textContent='TEMPLE SERVER OFFLINE';return}renderFrame()}
async function act(actor,action){
  if(busy||S?.reset_failed)return;busy=true;try{const d=await fetch('/api/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({actor,action})}).then(r=>r.json());S=d.state;lastAction={actor,action,result:d.message};renderFrame()}finally{busy=false}
}
document.querySelectorAll('.pad button').forEach(b=>b.addEventListener('click',()=>act(b.closest('.pad').dataset.actor,b.dataset.dir)));
$('#interact').addEventListener('click',()=>act('B','interact'));
async function resetGame(confirmFirst=true){
  if(busy)return;
  if(confirmFirst&&(S?.reset_count||0)<2&&!window.confirm('Start a new run? One of two resets will be used.'))return;
  busy=true;try{
    const data=await fetch('/api/reset',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'}).then(r=>r.json());
    S=data.state;lastAction=null;renderFrame();
  }catch(e){$('#msg').textContent='RESET FAILED — CHECK THAT THE SERVER IS RUNNING'}finally{busy=false}
}
$('#resetGame').addEventListener('click',()=>resetGame(true));
canvas.addEventListener('click',e=>{
  if(!S||S.reset_failed)return;const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)*W/r.width,y=(e.clientY-r.top)*H/r.height;
  const cell=[Math.floor(x/C),Math.floor(y/C)];if(!same(cell,LEVER))return;
  const bp=S.actors.B.pos,distance=Math.abs(bp[0]-LEVER[0])+Math.abs(bp[1]-LEVER[1]);
  if(S.lever_down){$('#msg').textContent='THE LEVER IS ALREADY DOWN — RED BRIDGE IS RAISED';return}
  if(!S.milestones?.B_crossed_blue_door){$('#msg').textContent='FIRST GUIDE BLUE B THROUGH THE OPEN BLUE GATE';return}
  if(distance>1){$('#msg').textContent='MOVE BLUE B NEXT TO THE LEVER, THEN CLICK IT';return}
  act('B','interact');
});
window.addEventListener('keydown',e=>{
  if(S?.reset_failed)return;
  const map={KeyW:['A','up'],KeyA:['A','left'],KeyS:['A','down'],KeyD:['A','right'],ArrowUp:['B','up'],ArrowLeft:['B','left'],ArrowDown:['B','down'],ArrowRight:['B','right']};
  const fallback={w:['A','up'],a:['A','left'],s:['A','down'],d:['A','right'],arrowup:['B','up'],arrowleft:['B','left'],arrowdown:['B','down'],arrowright:['B','right']};
  const move=map[e.code]||fallback[e.key.toLowerCase()];
  if(move){e.preventDefault();act(...move)}
});
function applyView(){document.querySelector('.red-pad').style.display=view==='B'?'none':'';document.querySelector('.blue-pad').style.display=view==='A'?'none':''}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{view=b.dataset.view;applyView();renderFrame()}));
if(new URLSearchParams(location.search).get('debug')==='0')$('#debug').hidden=true;
applyView();
if(new URLSearchParams(location.search).get('reset')==='1'){
  const cleanUrl=new URL(location.href);cleanUrl.searchParams.delete('reset');history.replaceState(null,'',cleanUrl.pathname+cleanUrl.search+cleanUrl.hash);
  resetGame(false);
}else load();

